// Demo concierge. Scripted for the staging preview; the live version would call an AI model grounded in
// the menu, hours, catering info and the family's own stories. All facts come from window.SITE_DATA
// (assets/menu-data.js, generated by build.mjs), so nothing here should be edited by hand.
(function () {
  const D = window.SITE_DATA || { restaurant: {}, sections: [] };
  const R = D.restaurant;
  const tel = `<a href="tel:${R.tel}">${R.phone}</a>`;

  const fab = document.createElement("button");
  fab.className = "chat-fab";
  fab.textContent = "Ask Carmine's";
  const panel = document.createElement("div");
  panel.className = "chat-panel";
  panel.innerHTML = `
    <div class="chat-head"><div><b>Carmine's</b><small>Hours · orders · catering · the menu</small></div><button aria-label="Close">×</button></div>
    <div class="chat-body"></div>
    <div class="chips"></div>
    <form class="chat-input"><input placeholder="Ask about hours, catering, a dish…" aria-label="Message"><button>Send</button></form>`;
  document.body.append(fab, panel);
  const body = panel.querySelector(".chat-body");
  const chips = panel.querySelector(".chips");
  const form = panel.querySelector("form");
  const input = form.querySelector("input");

  let flow = null; // catering lead capture
  let started = false;

  function add(html, who = "bot") {
    const d = document.createElement("div");
    d.className = "msg " + who;
    d.innerHTML = html;
    body.append(d);
    body.scrollTop = body.scrollHeight;
  }
  function setChips(list) {
    chips.innerHTML = "";
    list.forEach((t) => {
      const b = document.createElement("button");
      b.type = "button";
      b.textContent = t;
      b.onclick = () => send(t);
      chips.append(b);
    });
  }
  function reply(html, next) {
    const t = document.createElement("div");
    t.className = "msg bot typing";
    t.textContent = "typing…";
    body.append(t);
    body.scrollTop = body.scrollHeight;
    setTimeout(() => { t.remove(); add(html); setChips(next || defaults); }, 550);
  }
  const defaults = ["Hours", "Order take-out", "Catering", "Reservations", "Directions"];

  function answer(q) {
    const s = q.toLowerCase();
    if (flow) return cateringStep(q);
    const hit = D.sections.flatMap((sec) => sec.items).filter((i) => !i.ph).find((i) => s.includes(i.n.toLowerCase()));
    if (hit && !/(cater|tray)/.test(s))
      return reply(`<b>${esc(hit.n)}</b>${hit.price ? ` · ${esc(hit.price)}` : ""}<br>${esc(hit.d)}.<br><a class="btn ghost" href="/menu.html">See the full menu</a>`);
    if (/(book|reserv|table|tonight|party of)/.test(s))
      return reply(`We take reservations by phone. They're suggested for parties of 6 or more and on Fridays and Saturdays. Call ${tel}.`);
    if (/(order|pickup|pick up|take.?out|deliver)/.test(s))
      return reply(R.ubereats
        ? `You can order on Uber Eats, or call ${tel} for take-out.<br><a class="btn primary" href="${R.ubereats}" target="_blank" rel="noopener">Order on Uber Eats</a>`
        : `Call ${tel} for take-out.${(window.SITE_DATA.takeout || []).length ? ` Feeding a crowd? Our take-out specials feed 4–6: ${window.SITE_DATA.takeout.map((k) => `<b>${esc(k.n)}</b> $${k.p.toFixed(2)}`).join(" or ")}. <a href="/menu.html#takeout">See what's included</a>.` : ""} <small>(Staging: the Uber Eats link isn't added yet.)</small>`);
    if (/(cater|party|event|office|tray|banquet)/.test(s)) {
      flow = { step: 0, data: {} };
      return reply(`${esc(R.catering)} <a href="/catering.html">See catering</a>.<br>To start a quote: what's the date of your event?`, []);
    }
    if (/(hour|open|close|when)/.test(s)) return reply(`We're open ${esc(R.hours)}.`);
    if (/(park|where|address|located|direction)/.test(s)) return reply(`We're at <b>${esc(R.address)}</b>.`);
    if (/(owner|own|history|story|since|family|how long|fire|moved)/.test(s))
      return reply(`Carmine's has been family owned since ${esc(R.founded)} and is run today by ${esc(R.owners)}. <a href="/story.html">Read our story</a>.`);
    if (/(phone|call|contact)/.test(s)) return reply(`Call us at ${tel}.`);
    return reply(`I can help with hours, take-out, catering and reservations. For anything else, call ${tel}.`);
  }

  function cateringStep(q) {
    const f = flow;
    if (f.step === 0) { f.data.date = q; f.step = 1; return reply("Great. About how many guests?", ["10–25", "25–50", "50+"]); }
    if (f.step === 1) { f.data.guests = q; f.step = 2; return reply("Drop-off catering or a banquet at the restaurant?", ["Drop-off", "Banquet"]); }
    if (f.step === 2) { f.data.mode = q; f.step = 3; return reply("And the best email or phone number to reach you?", []); }
    if (f.step === 3) {
      f.data.contact = q;
      const d = f.data;
      flow = null;
      return reply(`Thank you! Your request: <b>${esc(d.guests)}</b> guests on <b>${esc(d.date)}</b>, ${esc(d.mode.toLowerCase())}. We'll follow up at ${esc(d.contact)}.<br><small>Demo only, nothing was sent. In the live version this request lands in the owner dashboard.</small>`);
    }
  }
  function esc(s) { return String(s).replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c])); }

  function send(text) {
    if (!text.trim()) return;
    add(esc(text), "me");
    answer(text);
  }
  function open() {
    panel.classList.add("open");
    if (!started) {
      started = true;
      add("Hi! I can answer questions about hours, take-out, catering and reservations at Carmine's.");
      setChips(defaults);
    }
    input.focus();
  }
  fab.onclick = () => (panel.classList.contains("open") ? panel.classList.remove("open") : open());
  panel.querySelector(".chat-head button").onclick = () => panel.classList.remove("open");
  form.onsubmit = (e) => { e.preventDefault(); const v = input.value; input.value = ""; send(v); };
  document.querySelectorAll("[data-open-chat]").forEach((el) => el.addEventListener("click", (e) => { e.preventDefault(); open(); }));
})();
